          margin-bottom: var(--s2); }
th, td { text-align: right; padding: var(--s1) var(--s2);
         border-bottom: 1px solid var(--rule); }
th:first-child, td:first-child { text-align: left; }
thead th { border-bottom: 2px solid var(--ink); color: var(--ink-soft);
           font-weight: 600; }
tbody tr:nth-child(even) { background: var(--paper-alt); }

/* ── method / privacy note ────────────────────────────────── */
.note { background: var(--paper-alt); border-left: 3px solid var(--c1);
        border-radius: 0 6px 6px 0; padding: var(--s3);
        font-size: var(--fs-sm); color: var(--ink-soft);
        max-width: var(--measure); }

/* ── responsive ───────────────────────────────────────────── */
@media (max-width: 60rem) { .kpis { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 34rem) {
  :root { --fs-cover: 1.75rem; --fs-kpi: 1.6rem; }
  .wrap   { padding: 0 var(--s2); }
  .kpis   { grid-template-columns: 1fr; }
  table   { font-size: var(--fs-xs); }
  th, td  { padding: var(--s1); }
